head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > E > ontoggleclick]<br/>트리 아이템의 토클 버튼을 마우스 버튼으로 클릭할 때 발생합니다.",
    "validation" : [        
        "renderType=viutual 이고 트리 아이템의 토클 버튼을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",                
        "node 파라미터로 클릭된 트리 아이템의 객체를 갖습니다.",
        "트리 아이템 객체의 속성을 통해 부모나 자식 트리 아이템에 접근할 수 있습니다.",        
        "node.{CheckBox Column ID} 속성값으로 트리 아이템의 CheckBox 항목에 설정된 Column ID 를 속성명으로 CheckBox 의 선택 여부를 true/false 로 갖습니다.",
        "node.{Depth Column ID} 속성값으로 트리 아이템의 Depth 항목에 설정된 Column ID 를 속성명으로 Depth(단계) 값을 갖습니다.",
        "node.{CheckBoxDisabled Column ID} 속성값으로 트리 아이템의 Depth 항목에 설정된 Column ID 를 속성명으로 Depth(단계) 값을 갖습니다.",
        "node.{Lebel Column ID} 속성값으로 트리 아이템의 Depth 항목에 설정된 Column ID 를 속성명으로 Depth(단계) 값을 갖습니다.",
        "node.rowStatus 속성값으로 트리 아이템의 Depth 항목에 설정된 Column ID 를 속성명으로 Depth(단계) 값을 갖습니다.",
        "node.{Value Column ID} 속성값으로 트리 아이템의 Depth 항목에 설정된 Column ID 를 속성명으로 Depth(단계) 값을 갖습니다.",
        "index 파라미터로 클릭된 트리 아이템의 인덱스값을 갖습니다.",
        "rendered 파라미터로 클릭된 트리 아이템의 자식 아이템 렌더링 상태를 true/false 로 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType : "virtual",
        showCheckbox : true,
    }    

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["ontoggleclick"]);

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px;height:350px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );

    target1.spanAll(true);
}



scwin.target1_ontoggleclick = function (node, index, rendered) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontoggleclick=====");

    wf_body_bottom.getObj("scwin").setReturnValue("node : " + node);

    if (node) {
        wf_body_bottom.getObj("scwin").setReturnValue("node.checkbox : " + node.checkbox);
        wf_body_bottom.getObj("scwin").setReturnValue("node.depth : " + node.depth);
        wf_body_bottom.getObj("scwin").setReturnValue("node.disabled : " + node.disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("node.label : " + node.label);
        wf_body_bottom.getObj("scwin").setReturnValue("node.rowStatus : " + node.rowStatus);        
        wf_body_bottom.getObj("scwin").setReturnValue("node.value : " + node.value);        
    } 

    wf_body_bottom.getObj("scwin").setReturnValue("index : " + index);   
    wf_body_bottom.getObj("scwin").setReturnValue("rendered : " + rendered); 
}
